    pyq(RY, 385, 'q-pl-sellers', 'Arun buys one kilogram of apples for Rs. 120 and sells it to Swati gaining 25%. Swati sells it to Divya and Divya again sells it for Rs. 198, making a profit of 10%. What is the profit percentage made by Swati?', ['25%', '20%', '16.67%', '15%'], 'b', ['Swati paid 120 × 1.25 = Rs. 150.', "Divya paid 198 ÷ 1.1 = Rs. 180. Swati's profit = 30/150 = 20%."],
        lambda: float((lambda: (198 / 1.1 - 120 * 1.25) / (120 * 1.25) * 100)()), 20.0, 1e-06, tech=['multiplier'], optvals=[opt_val(o) for o in ['25%', '20%', '16.67%', '15%']]),
